43	/**
44	 * Clustering Strategy based on following.
45	 * 1) Creates clustering groups based on max size allowed per group.
46	 * 2) Excludes files that are greater than 'small.file.limit' from clustering plan.
47	 */
48	@Slf4j
49	public class FlinkSizeBasedClusteringPlanStrategy<T>
50	    extends PartitionAwareClusteringPlanStrategy<T, List<HoodieRecord<T>>, List<HoodieKey>, List<WriteStatus>> {
51	
52	  public FlinkSizeBasedClusteringPlanStrategy(HoodieTable table,
53	                                              HoodieEngineContext engineContext,
54	                                              HoodieWriteConfig writeConfig) {
55	    super(table, engineContext, writeConfig);
56	  }
57	
58	  @Override
59	  protected Pair<Stream<HoodieClusteringGroup>, Boolean> buildClusteringGroupsForPartition(String partitionPath, List<FileSlice> fileSlices) {
60	    return super.buildClusteringGroupsForPartition(partitionPath, fileSlices);
61	  }
62	
63	  @Override
64	  protected Map<String, String> getStrategyParams() {
65	    Map<String, String> params = new HashMap<>();
66	    if (!StringUtils.isNullOrEmpty(getWriteConfig().getClusteringSortColumns())) {
67	      params.put(PLAN_STRATEGY_SORT_COLUMNS.key(), getWriteConfig().getClusteringSortColumns());
68	    }
69	    return params;
70	  }
71	
72	  @Override
73	  protected Stream<FileSlice> getFileSlicesEligibleForClustering(final String partition) {
74	    return super.getFileSlicesEligibleForClustering(partition)
75	        // Only files that have base file size smaller than small file size are eligible.
76	        .filter(slice -> slice.getBaseFile().map(HoodieBaseFile::getFileSize).orElse(0L) < getWriteConfig().getClusteringSmallFileLimit());
77	  }
78	}
